GROUPS.unshift(['Workshop',[['home','Workshop desk','PC'],['wifi-rf','Wi-Fi & RF budget','RF'],['ndp','IPv6 neighbor discovery','ND'],['qos','QoS queue workshop','Q'],['capture','Capture investigation','PCAP'],['automation','Automation change planner','API']]]);
const PATHS=[['Addressing','ipv4','Turn bits into a working address plan.'],['Routing','topology','Explore paths, policies and failures.'],['Wireless','wifi-rf','Connect signal budgets to RF decisions.'],['Operations','capture','Investigate evidence before making a change.'],['Practice','broken','Build confidence with failure scenarios.']];
function workshopRender(id){const ids=['home','wifi-rf','ndp','qos','capture','automation'];if(!ids.includes(id))return false;if(id==='home'){document.getElementById('surface').innerHTML='<section class="workshop-hero"><div><span class="eyebrow">THE NETWORK WORKSHOP / PARAM CHAWLA</span><h2>Understand the path.<br>Build with confidence.</h2><p>A personal workbench for the engineer who wants to know why a network works—and where it breaks.</p><button class="primary" data-jump="wifi-rf">Explore the wireless lab →</button></div><div class="desk-art" aria-hidden="true"><span>01 / OBSERVE</span><div>HOST ─── SWITCH<br>│ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; │<br>AP ───── ROUTER</div><span>02 / TEST &nbsp; 03 / EXPLAIN</span></div></section><div class="path-grid">'+PATHS.map(([t,d,s],i)=>'<button class="path-card" data-jump="'+d+'"><span>0'+(i+1)+'</span><h3>'+t+'</h3><p>'+s+'</p><strong>Open workbench ↗</strong></button>').join('')+'</div>'+card('New on the workbench','<div class="new-labs">'+ids.slice(1).map(d=>'<button data-jump="'+d+'">'+esc(PAGES.find(p=>p.id===d).title)+' ↗</button>').join('')+'</div>')+card('A way to practice', '<div class="grid equal"><div><h3>Learn → Experiment → Troubleshoot</h3><p>Choose a model. Change one variable. Predict the outcome before running it. Explain the result, then introduce a failure.</p></div><div><h3>Your field notes</h3><p>Write down the symptom, the evidence and the smallest change that fixes it. A successful test is stronger than a guessed configuration.</p></div></div>');document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>navigate(b.dataset.jump));return true;}
if(id==='wifi-rf'){ $('surface').innerHTML=card('Learn · A link budget is a starting point', '<p>Received power follows transmit power + antenna gains − path loss − other losses. Free-space loss assumes an unobstructed path; walls, fading, interference and receiver characteristics need separate measurements.</p>')+card('Experiment · RF link budget','<div class="fields">'+input('rf-f','Frequency (MHz)',5180,'number')+input('rf-d','Distance (metres)',20,'number')+input('rf-t','Transmit power (dBm)',20,'number')+input('rf-g','Combined antenna gain (dBi)',4,'number')+input('rf-l','Other losses (dB)',10,'number')+input('rf-n','Noise floor (dBm)',-95,'number')+'</div>'+btn('rf-run','Calculate budget',true)+out())+card('Troubleshoot · Before raising power','<p>Check channel utilization, retries, client transmit capability and roaming. A strong AP signal does not guarantee a healthy return path. Validate on site; this model predicts neither data rate nor coverage.</p>');const run=()=>{const f=+$('rf-f').value,d=+$('rf-d').value;if(f<=0||d<=0)throw Error('Use a positive frequency and distance.');const loss=20*Math.log10(d/1000)+20*Math.log10(f)+32.44,p=+$('rf-t').value+ +$('rf-g').value-loss- +$('rf-l').value;$('output').innerHTML=stats([['Free-space path loss',loss.toFixed(1)+' dB'],['Estimated received power',p.toFixed(1)+' dBm'],['Estimated SNR',(p- +$('rf-n').value).toFixed(1)+' dB']]);};action('rf-run',run);run();}
if(id==='ndp'){let step=0;const scenes=[['Resolve the next hop','A host chooses an on-link destination or its default router. Router advertisements and prefix information influence that decision.'],['Neighbor Solicitation','An ICMPv6 NS targets the neighbor’s solicited-node multicast group. IPv6 uses NDP rather than ARP.'],['Neighbor Advertisement','The target responds with an NA and link-layer information. The sender updates its neighbor cache.'],['Reachability state','The cache can transition from REACHABLE to STALE, then DELAY and PROBE when reachability needs confirmation.']];$('surface').innerHTML=card('Learn · IPv6 on the local link','<p>NDP includes address resolution, router and prefix discovery, duplicate address detection and neighbor reachability. This walk focuses on address resolution.</p>')+card('Experiment · Derive a multicast destination','<div class="fields">'+input('nd-address','Target IPv6 address','2001:db8::1234:5678')+'</div>'+btn('nd-run','Derive solicited-node address',true)+out()+ '<div class="actions">'+btn('nd-prev','Previous step')+btn('nd-next','Next step')+'</div><div id="nd-scene"></div>')+card('Troubleshoot · NS with no NA','<p>Check the target address, VLAN membership, multicast delivery and ICMPv6 filtering. DAD uses an unspecified source address and serves a different purpose from normal neighbor resolution.</p>');const draw=()=>{$('nd-scene').innerHTML='<div class="eyebrow">Step '+(step+1)+' / 4</div><h3>'+scenes[step][0]+'</h3><p>'+scenes[step][1]+'</p>';};const run=()=>{const expanded=Net.expand6($('nd-address').value).join(':');const hex=expanded.replace(/:/g,'').slice(-6);$('output').innerHTML=stats([['Solicited-node multicast','ff02::1:ff'+hex.slice(0,2)+':'+hex.slice(2)],['Ethernet multicast','33:33:ff:'+hex.match(/../g).join(':')]]);};action('nd-run',run);action('nd-next',()=>{step=(step+1)%4;draw();});action('nd-prev',()=>{step=(step+3)%4;draw();});run();draw();}
if(id==='qos'){$('surface').innerHTML=card('Learn · Delay before priority','<p>Serialization delay is the time required to put a packet onto a link. Queueing adds waiting time. Marking DSCP alone does not create a scheduling policy or additional capacity.</p>')+card('Experiment · A simplified FIFO queue','<div class="fields">'+input('q-rate','Link speed (Mbps)',10,'number')+input('q-size','Packet size (bytes)',1500,'number')+input('q-backlog','Bytes queued ahead',60000,'number')+'</div>'+btn('q-run','Estimate delay',true)+out())+card('Troubleshoot · Real-time traffic','<p>Measure congestion and loss, verify the trust boundary and classify traffic intentionally. Priority queues need capacity and policing limits; otherwise other traffic can starve. This FIFO model excludes propagation, processing and encapsulation overhead.</p>');const run=()=>{const rate=+$('q-rate').value,size=+$('q-size').value,back=+$('q-backlog').value;if(rate<=0||size<=0||back<0)throw Error('Use positive speed and size, and a non-negative queue.');$('output').innerHTML=stats([['Serialization', (size*8/(rate*1000)).toFixed(3)+' ms'],['Queue waiting',(back*8/(rate*1000)).toFixed(3)+' ms'],['Total modeled delay',((size+back)*8/(rate*1000)).toFixed(3)+' ms']]);};action('q-run',run);run();}
if(id==='capture'){const cases=[['Repeated SYN, no reply','0.000 Client → Server SYN\n1.000 Client → Server SYN (retry)\n3.000 Client → Server SYN (retry)','No response is visible. Check capture location, forward/return routing, filtering and server availability. The trace alone does not identify which one failed.'],['TCP reset after SYN','0.000 Client → Server SYN\n0.012 Server → Client RST, ACK','A reset is visible. Verify its source and whether a listener exists; a middlebox may also generate a reset.'],['DNS reply, connection timeout','0.000 Client → DNS Query A example.test\n0.010 DNS → Client Answer 203.0.113.10\n0.015 Client → 203.0.113.10 SYN\n1.015 Client → 203.0.113.10 SYN (retry)','Name resolution succeeded in this scene. Investigate transport reachability separately; an answer does not prove the destination service is reachable.']];$('surface').innerHTML=card('Learn · Evidence before diagnosis','<p>Capture at a useful point, record timestamps and identify what the trace can and cannot prove. These are synthetic traces, not an uploaded PCAP analyzer.</p>')+card('Experiment · Investigate a trace',select('cap-case','Scenario',cases.map((x,i)=>[i,x[0]]))+out()+btn('cap-reveal','Reveal investigation notes',true)+'<div id="cap-notes"></div>')+card('Troubleshoot · Capture quality','<p>Check packet drops, snap length, clock alignment and whether both directions are visible. Retransmissions inferred from a partial capture can be misleading.</p>');const run=()=>{$('output').innerHTML='<pre>'+esc(cases[+$('cap-case').value][1])+'</pre>';$('cap-notes').innerHTML='';};$('cap-case').onchange=run;action('cap-reveal',()=>{$('cap-notes').innerHTML=hint(cases[+$('cap-case').value][2]);});run();}
if(id==='automation'){$('surface').innerHTML=card('Learn · Make the change reviewable','<p>A repeatable change starts with explicit intent, bounded targets, pre-checks and rollback. This planner creates local notes; it does not connect to devices or run commands.</p>')+card('Experiment · Change plan',area('a-target','Targets (one per line)','R1\nR2')+area('a-intent','Desired change','Apply a reviewed management ACL')+area('a-pre','Pre-change evidence','Record current ACL and management reachability')+area('a-post','Post-change verification','Verify permitted management access and denied test traffic')+area('a-rollback','Rollback procedure','Restore the saved ACL if approved checks fail')+btn('a-run','Build review plan',true)+out()+btn('a-save','Download plan'))+card('Troubleshoot · Partial success','<p>Define stop conditions before execution. Check for out-of-band access, staged rollout and configuration drift. Never include passwords or private keys in exported plans.</p>');const run=()=>{const targets=$('a-target').value.split(/\n/).map(x=>x.trim()).filter(Boolean);if(!targets.length||!$('a-intent').value.trim()||!$('a-rollback').value.trim())throw Error('Provide targets, change intent and rollback.');const plan={owner:'Param Chawla',targets,intent:$('a-intent').value,precheck:$('a-pre').value,postcheck:$('a-post').value,rollback:$('a-rollback').value,stopCondition:'Stop rollout when a verification fails; investigate before continuing.'};$('output').innerHTML='<pre>'+esc(JSON.stringify(plan,null,2))+'</pre>';return plan;};action('a-run',run);action('a-save',()=>download('network-change-plan.json',JSON.stringify(run(),null,2)));run();}return true;}
document.getElementById('tracks').innerHTML='<button data-track="home">Workshop desk</button>'+PATHS.map(([t,id])=>'<button data-track="'+id+'">'+t+'</button>').join('');document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>navigate(b.dataset.track));

